<?php
declare( strict_types = 1 );

namespace Automattic\WooCommerce\Internal\Blocks;

use Automattic\WooCommerce\Blocks\Domain\Package;

/**
 * Loads asset registration generated by the block-library wp-build package.
 *
 * @since 11.0.0
 */
class BlockLibraryScriptRegistry {

	/**
	 * Packaged path for the generated asset registration entry point.
	 */
	private const BUILD_FILE_PATH = 'assets/client/blocks/build.php';

	/**
	 * Package instance.
	 *
	 * @var Package
	 */
	private Package $package;

	/**
	 * Constructor.
	 *
	 * @param Package $package Package instance.
	 */
	public function __construct( Package $package ) {
		$this->package = $package;
	}

	/**
	 * Load generated asset registration.
	 *
	 * @internal
	 */
	final public function init(): void {
		$build_file = $this->package->get_path( self::BUILD_FILE_PATH );
		if ( ! file_exists( $build_file ) ) {
			return;
		}

		require_once $build_file;

		if ( did_action( 'wp_default_scripts' ) && function_exists( 'woocommerce_blocks_block_library_register_package_scripts' ) ) {
			woocommerce_blocks_block_library_register_package_scripts( wp_scripts() );
		}
	}
}
